import { cva, type VariantProps } from "class-variance-authority"

// [&_svg]:fill-current added — Material Symbols SVGs are fill-based.
// See DIVERGENCES.md §kbd-1.
export const kbdVariants = cva(
  "pointer-events-none inline-flex h-5 w-fit min-w-5 items-center justify-center gap-1 rounded-sm bg-muted px-1 font-sans text-xs font-medium text-muted-foreground select-none in-data-[slot=tooltip-content]:bg-background/20 in-data-[slot=tooltip-content]:text-background dark:in-data-[slot=tooltip-content]:bg-background/10 [&_svg]:fill-current [&_svg:not([class*='size-'])]:size-3",
  {
    variants: {
      variant: {
        default: "bg-muted text-muted-foreground",
        primary: "bg-background/20 text-background dark:bg-background/10",
      },
    },
    defaultVariants: { variant: "default" },
  }
)

export type KbdVariants = VariantProps<typeof kbdVariants>
export type KbdVariant = NonNullable<KbdVariants["variant"]>

import {
  ChangeDetectionStrategy,
  Component,
  computed,
  input,
} from "@angular/core"

import { cn } from "@/lib/utils"

import { kbdVariants, type KbdVariant } from "./kbd.variants"

/**
 * Angular port of @force-ui/kbd (radix-force-ui style).
 *
 * Attribute selectors on native <kbd> elements — usage:
 *   <kbd uiKbd>Ctrl</kbd>
 *   <kbd uiKbd variant="primary">⌘</kbd>
 *   <span uiKbdGroup><kbd uiKbd>⌘</kbd><kbd uiKbd>K</kbd></span>
 *
 * variant="default" — muted pill for light surfaces.
 * variant="primary" — translucent pill for placement on a solid/brand surface
 * (e.g. inside a default button or tooltip). Matches Figma Background=Primary.
 */
@Component({
  selector: "[uiKbd]",
  standalone: true,
  templateUrl: "./kbd.component.html",
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    "data-slot": "kbd",
    "[attr.data-variant]": "variant()",
    "[class]": "classes()",
  },
})
export class KbdComponent {
  readonly variant = input<KbdVariant>("default")
  readonly className = input<string | undefined>(undefined, { alias: "class" })

  protected readonly classes = computed(() =>
    cn(kbdVariants({ variant: this.variant() }), this.className())
  )
}

@Component({
  selector: "[uiKbdGroup]",
  standalone: true,
  templateUrl: "./kbd.component.html",
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    "data-slot": "kbd-group",
    "[class]": "classes()",
  },
})
export class KbdGroupComponent {
  readonly className = input<string | undefined>(undefined, { alias: "class" })

  protected readonly classes = computed(() =>
    cn("cn-kbd-group inline-flex items-center", this.className())
  )
}

export {
  KbdComponent as Kbd,
  KbdGroupComponent as KbdGroup,
} from "./kbd.component"
export { kbdVariants, type KbdVariants, type KbdVariant } from "./kbd.variants"
